const listTenants = `-- name: ListTenants :many


SELECT id, entity_id, kode, nama, paket_tier, status, max_users, max_lokasi, kontak_email, kontak_telepon, versi_skema, version, created_at, updated_at, deleted_at
FROM core_tenants
WHERE deleted_at IS NULL
  AND ($1::text IS NULL
       OR kode ILIKE '%' || $1::text || '%'
       OR nama ILIKE '%' || $1::text || '%')
  AND ($2::text IS NULL OR status::text = $2::text)
  AND ($3::text IS NULL OR paket_tier::text = $3::text)
ORDER BY id ASC
LIMIT $5::int OFFSET $4::int
`

type ListTenantsParams struct {
	Search pgtype.Text `json:"search"`
	Status pgtype.Text `json:"status"`
	Tier   pgtype.Text `json:"tier"`
	Offset int32       `json:"offset"`
	Limit  int32       `json:"limit"`
}

// Query fitur TENANTS modul core — padanan TenantsRepository NestJS
// (modules/core/repositories/tenants/tenants.repository.ts, ddl/22-core-tenants).
// Tabel: core_tenants, core_users_tenants, core_tenant_modules,
// core_tenant_features, core_tenant_settings, core_tenant_events + katalog
// global core_modules / core_modules_features + identitas core_users.
// Semua method menerima executor (pool | tx) — wrapper repository meneruskan
// executor yang dipilih service (baca non-tx, mutasi dalam SATU tx bisnis).
// ================================================================
// Baca — daftar / detail / dup kode / konteks user
// ================================================================
// Daftar tenant paging (?page&limit&search&status&tier) — soft-delete aware
// (deleted_at IS NULL); search menyasar kode + nama (ilike, tanpa escape —
// persis Drizzle). Nilai kosong/nihil param = filter dilewati.
func (q *Queries) ListTenants(ctx context.Context, arg ListTenantsParams) ([]CoreTenant, error) {
	rows, err := q.db.Query(ctx, listTenants,
		arg.Search,
		arg.Status,
		arg.Tier,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []CoreTenant
	for rows.Next() {
		var i CoreTenant
		if err := rows.Scan(
			&i.ID,
			&i.EntityID,
			&i.Kode,
			&i.Nama,
			&i.PaketTier,
			&i.Status,
			&i.MaxUsers,
			&i.MaxLokasi,
			&i.KontakEmail,
			&i.KontakTelepon,
			&i.VersiSkema,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

